import sys

def Reduced_String(k, s):
    stack = []
    count_stack = []

    for char in s:
        if stack and stack[-1] == char:
            count_stack[-1] += 1
            if count_stack[-1] == k:
                stack.pop()
                count_stack.pop()
        else:
            stack.append(char)
            count_stack.append(1)

    return ''.join(stack)

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    try:
        k = int(lines[0].strip())
        s = lines[1].strip()
    except IndexError:
        return

    result = Reduced_String(k, s)
    sys.stdout.write(result + '\n')

if __name__ == "__main__":
    main()
